import inspect
import typing

from jsilib import _utils

from .interface import IMethodHandlerRegistry

__all__ = export = _utils.ExportList()


@export
class Namespace(IMethodHandlerRegistry):
    """Groups methods and possibly nested namespaces together.

    JSONRPC server method names are strings concatenated with a period sign.

    Names without a period belong to the root namespace. For example::

        foo

    Names with a period belong to the namespace which name is on the left side
    of the period, and method name on the right side. For example::

        foo.bar  ->  foo (namespace), bar (method)

    There can be multiple period characters in single method name. In such
    situation, method name is still on the right, while all what is left on the
    left side is a name a nested namespace. For example::

        foo.bar.spam  ->  foo.bar (nested namespace), spam (method)
    """

    def __init__(self):
        self._handlers = {}

    def find_method(self, name: str) -> typing.Optional[IMethodHandlerRegistry.MethodHandlerType]:
        parts = name.split('.', 1)
        if len(parts) == 1:
            handler = self._handlers.get(parts[0])
            if handler is None or isinstance(handler, IMethodHandlerRegistry):
                return None
            return handler
        prefix, postfix = parts
        namespace = self._handlers.get(prefix)
        if not isinstance(namespace, IMethodHandlerRegistry):
            return None
        return namespace.find_method(postfix)

    def list_methods(self) -> typing.Iterator[typing.Tuple[str, IMethodHandlerRegistry.MethodHandlerType]]:
        for name, value in self._handlers.items():
            if not isinstance(value, IMethodHandlerRegistry):
                yield name, value

    def list_namespaces(self) -> typing.Iterator[typing.Tuple[str, 'IMethodHandlerRegistry']]:
        for name, value in self._handlers.items():
            if isinstance(value, IMethodHandlerRegistry):
                yield name, value

    def register_method(self, name: str, handler: IMethodHandlerRegistry.MethodHandlerType):
        self._validate_name_availability(name)
        self._handlers[name] = handler

    def register_namespace(self, ns: 'IMethodHandlerRegistry', prefix: str = None):
        if prefix is None:
            for name, method in ns.list_methods():
                self.register_method(name, method)
            for name, ns in ns.list_namespaces():
                self.register_namespace(ns, prefix=name)
        else:
            self._validate_name_availability(prefix)
            self._handlers[prefix] = ns

    def _validate_name_availability(self, name: str):
        if name in self._handlers:
            raise ValueError(f"method handler already exists for name {name!r}")

    def method(self, name: str = None):
        """Decorate a function to become a method handler.

        This is decorator-based version of :meth:`register_method` method.

        :param name:
            Name to be used as a method name.

            If this is skipped, then decorated function's name will be used
            instead.
        """
        if inspect.iscoroutinefunction(name):
            self.register_method(name.__name__, name)
            return name
        else:

            def decorator(handler: IMethodHandlerRegistry.MethodHandlerType):
                self.register_method(name, handler)
                return handler

            return decorator
